const leads = $('Get All Leads').all().map(i => i.json);
const appointments = $('Get All Appointments').all().map(i => i.json);
const now = new Date();
const today = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const last7days = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

// Lead stats
const totalLeads = leads.length;
const newLeads = leads.filter(l => l.STATUS === 'NEW').length;
const hotLeads = leads.filter(l => l.LEAD_SCORE === 'HOT').length;
const warmLeads = leads.filter(l => l.LEAD_SCORE === 'WARM').length;
const coldLeads = leads.filter(l => l.LEAD_SCORE === 'COLD' || l.STATUS === 'COLD').length;
const qualifiedLeads = leads.filter(l => l.STATUS === 'QUALIFIED').length;
const bookedLeads = leads.filter(l => l.BOOKED === 'TRUE').length;
const followingUp = leads.filter(l => l.STATUS === 'FOLLOWING_UP').length;
const conversionRate = totalLeads > 0 ? ((bookedLeads / totalLeads) * 100).toFixed(1) : 0;

// New this week
const newThisWeek = leads.filter(l => {
  const created = l.CREATED_AT ? new Date(l.CREATED_AT) : null;
  return created && created >= last7days;
}).length;

// Source breakdown
const sources = {};
leads.forEach(l => {
  const src = l.SOURCE || 'unknown';
  sources[src] = (sources[src] || 0) + 1;
});
const sourceLines = Object.entries(sources).map(([k,v]) => `  ${k}: ${v}`).join('\n');

// Appointment stats
const totalAppts = appointments.length;
const confirmedAppts = appointments.filter(a => a.STATUS === 'CONFIRMED').length;
const upcomingAppts = appointments.filter(a => {
  const d = a.APPOINTMENT_DATE ? new Date(a.APPOINTMENT_DATE) : null;
  return d && d >= now;
}).length;

// Needs attention
const needsFollowUp = leads.filter(l => {
  const last = l.LAST_CONTACT ? new Date(l.LAST_CONTACT) : null;
  const hoursAgo = last ? (now - last) / (1000*60*60) : 9999;
  return hoursAgo > 48 && l.BOOKED !== 'TRUE' && l.STATUS !== 'COLD';
}).length;

const report = `
================================================
        DAILY SALES PIPELINE REPORT
        ${today}
================================================

📊 LEAD OVERVIEW
  Total Leads:        ${totalLeads}
  New This Week:      ${newThisWeek}
  New (Uncontacted):  ${newLeads}
  Qualified:          ${qualifiedLeads}
  Following Up:       ${followingUp}
  Gone Cold:          ${coldLeads}

🔥 LEAD SCORES
  HOT:   ${hotLeads}
  WARM:  ${warmLeads}
  COLD:  ${coldLeads}

📅 APPOINTMENTS
  Total Booked:   ${bookedLeads} leads
  Confirmed Appts: ${confirmedAppts}
  Upcoming:       ${upcomingAppts}
  Conversion Rate: ${conversionRate}%

⚠️  NEEDS ATTENTION
  Leads with no contact in 48h+: ${needsFollowUp}

📍 LEAD SOURCES
${sourceLines}

================================================
`;

return [{ json: { report, totalLeads, bookedLeads, conversionRate, hotLeads, needsFollowUp, newThisWeek } }];
